cd /target/libgit2-crustify/crustify/.worktrees/modules/libgit2/src/util/thread.c/integration; mkdir -p examples && cat > examples/bsan_tls_growth.rs <<'EOF'
// Scratch reproducer (not committed): the cost of a thread-local lookup as one thread
// repeats it, as C's threadstate_get does through git_tlsdata_get on every git_error_clear.
use libgit2_crustify::libgit2::src::util::thread::TlsKey;
use std::time::Instant;

fn main() {
    let key: TlsKey<usize> = TlsKey::new(None).unwrap();
    key.set(Some(7)).unwrap();
    let chunk: usize = std::env::args().nth(1).map_or(2000, |a| a.parse().unwrap());
    let chunks: usize = std::env::args().nth(2).map_or(8, |a| a.parse().unwrap());
    let mut s = 0;
    for c in 0..chunks {
        let t = Instant::now();
        for _ in 0..chunk {
            s += key.with(|v| *v.unwrap());
        }
        println!("chunk {c}: {:.1} us per lookup", t.elapsed().as_secs_f64() * 1e6 / chunk as f64);
    }
    assert_eq!(s, 7 * chunk * chunks);
}
EOF
export CARGO_BUILD_JOBS=32; timeout 1500 crustify/scripts/cargo-variant.sh bsan run --example bsan_tls_growth -- 2000 8 2>&1 | grep -E "chunk|error|panicked" | head -20

